      // Projecting all 8 corners through the view matrix makes this correct for any
      // camera angle — including axonometric off-axis views where size.y alone would
      // undercount the vertical screen extent contributed by the X and Z axes.
      let resolvedZoom;
      if (Number.isFinite(zoom)) {
