function makeArrow({
  shaftColor = 0x008000,
  coneColor = shaftColor,
  radius = 0.025,
  coneRadius = 0.105,
  coneLength = 0.28,
  opacity = 1
} = {}) {
  const group = new THREE.Group();
  const matShaft = new THREE.MeshBasicMaterial({
    color: shaftColor,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
  const matCone = new THREE.MeshBasicMaterial({
    color: coneColor,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 16), matShaft);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 24), matCone);
  group.add(shaft, cone);
  group.userData.shaft = shaft;
  group.userData.cone = cone;
  group.userData.radius = radius;
  group.userData.coneRadius = coneRadius;
  group.userData.coneLength = coneLength;
  group.userData.opacity = opacity;
  scene.add(group);
  return group;
}

const qForward = new THREE.Vector3(0, 1, 0);
function updateArrow(group, start, dir, length) {
  const dvec = dir.clone();
  if (dvec.lengthSq() < 1e-8) dvec.set(0, 1, 0);
  dvec.normalize();

  const shaft = group.userData.shaft;
  const cone = group.userData.cone;
  const coneLength = Math.min(group.userData.coneLength, Math.max(0.08, length * 0.35));
  const shaftLength = Math.max(0.001, length - coneLength);
  const quat = new THREE.Quaternion().setFromUnitVectors(qForward, dvec);

  shaft.position.copy(start).addScaledVector(dvec, shaftLength / 2);
  shaft.quaternion.copy(quat);
  shaft.scale.set(group.userData.radius, shaftLength, group.userData.radius);

  cone.position.copy(start).addScaledVector(dvec, shaftLength + coneLength / 2);
  cone.quaternion.copy(quat);
  cone.scale.set(group.userData.coneRadius, coneLength, group.userData.coneRadius);

  group.userData.start = start.clone();
  group.userData.dir = dvec.clone();
  group.userData.length = length;
}

function setArrowOpacity(group, opacity) {
  for (const child of group.children) {
    child.material.opacity = opacity;
    child.material.transparent = opacity < 1;
    child.material.depthWrite = opacity >= 1;
    child.material.needsUpdate = true;
  }
}

