function updateScene() {
  state.brdfType = ui.brdfType.value;
  state.incidentTheta = Number(ui.incidentTheta.value);
  state.normalTilt = Number(ui.normalTilt.value);
  ui.incidentThetaVal.textContent = `${state.incidentTheta}°`;
  ui.normalTiltVal.textContent = `${state.normalTilt}°`;

  const { n, t, b, incidentTowardSurface, reflected } = currentDirections();
  const origin = new THREE.Vector3(0, 0.02, 0);

  const source = incidentTowardSurface.clone().multiplyScalar(-5.0);
  source.y += 0.02;
  updateArrow(incomingRay, source, incidentTowardSurface, source.distanceTo(origin) - 0.03);

  const pStart = incidentTowardSurface.clone().multiplyScalar(-1.38).add(origin);
  updateArrow(pArrow, pStart, incidentTowardSurface, 1.25);

  updateArrow(normalArrow, origin, n, 1.42);
  updateArrow(qArrow, origin, reflected, 2.2);

  for (let i = 0; i < scatterArrows.length; i++) {
    const spec = scatterSpecs[i];
    const hemiDir = new THREE.Vector3()
      .copy(n).multiplyScalar(Math.cos(spec.polar))
      .addScaledVector(t, Math.sin(spec.polar) * Math.cos(spec.phi))
      .addScaledVector(b, Math.sin(spec.polar) * Math.sin(spec.phi))
      .normalize();

    let length;
    let opacity;
    if (state.brdfType === 'Lambertian') {
      length = 0.96;
      opacity = 0.48;
    } else {
      const align = Math.max(0, hemiDir.dot(reflected));
      const weight = Math.pow(align, 14);
      length = 0.28 + 1.7 * weight;
      opacity = 0.20 + 0.68 * weight;
    }
    updateArrow(scatterArrows[i], origin, hemiDir, length);
    setArrowOpacity(scatterArrows[i], opacity);
  }

  const s = 0.36;
  const anglePts = [
    origin.clone().addScaledVector(t, s),
    origin.clone().addScaledVector(t, s).addScaledVector(n, s),
    origin.clone().addScaledVector(n, s),
    origin.clone()
  ];
  angleGeom.setFromPoints(anglePts);
  angleGeom.computeBoundingSphere();

  updateLabels({
    lin: source.clone().lerp(origin, 0.35).add(new THREE.Vector3(-0.15, 0.45, 0.12)),
    p: pStart.clone().lerp(origin, 0.43).add(new THREE.Vector3(-0.18, 0.22, 0)),
    n: origin.clone().addScaledVector(n, 1.15).add(new THREE.Vector3(-0.13, 0.1, 0)),
    q: origin.clone().addScaledVector(reflected, 1.1).add(new THREE.Vector3(0.16, 0.18, 0.02)),
    lout: origin.clone().addScaledVector(reflected, 2.35).add(new THREE.Vector3(0.75, 0.5, 0.08))
  });
}

