// @FIGURE_CODE_BEGIN
// surface plane → PlaneGeometry(8,6), bright lime mesh lying in XZ plane
// black border → Line loop following the four edges of the surface plane
// origin point → small black torus ring at ray/surface intersection
// normal n → thick black cylinder+cone arrow from origin along tilted local normal
// incoming ray → long yellow/orange cylinder+cone arrow descending toward origin
// p vector → shorter red cylinder+cone arrow collinear with incoming direction
// q vector → highlighted thick dark-green cylinder+cone arrow along mirror/outgoing direction
// BRDF lobe → 17 translucent green cylinder+cone arrows in a hemisphere around n
// right-angle marker → black Line square at base of n in local tangent-normal plane
// labels → HTML billboards for ℓ_in(λ), p, n, q, and ℓ_out = F(ℓ_in,n,λ,p,q)

document.getElementById('btnReset').style.display = 'block';

scene.add(new THREE.AmbientLight(0xffffff, 1));

const state = {
  brdfType: 'Lambertian',
  incidentTheta: 45,
  normalTilt: 0
};

const ui = {
  brdfType: document.getElementById('brdfType'),
  incidentTheta: document.getElementById('incidentTheta'),
  incidentThetaVal: document.getElementById('incidentThetaVal'),
  normalTilt: document.getElementById('normalTilt'),
  normalTiltVal: document.getElementById('normalTiltVal'),
  prevStep: document.getElementById('prevStep'),
  nextStep: document.getElementById('nextStep'),
  stepTitle: document.getElementById('stepTitle'),
  stepText: document.getElementById('stepText')
};

const surface = new THREE.Mesh(
  new THREE.PlaneGeometry(8, 6),
  new THREE.MeshBasicMaterial({ color: 0x7fff00, side: THREE.DoubleSide })
);
surface.rotation.x = -Math.PI / 2;
surface.position.y = -0.018;
scene.add(surface);
registerInteractive(surface, {
  title: 'Reflecting surface',
  tooltip: 'BRDF surface',
  body: 'The bright green plane is the material surface. The BRDF describes how light arriving at one point is redistributed into outgoing directions.'
});

const border = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-4, 0.006, -3),
    new THREE.Vector3(4, 0.006, -3),
    new THREE.Vector3(4, 0.006, 3),
    new THREE.Vector3(-4, 0.006, 3),
    new THREE.Vector3(-4, 0.006, -3)
  ]),
  new THREE.LineBasicMaterial({ color: 0x080808 })
);
scene.add(border);

const originRing = new THREE.Mesh(
  new THREE.TorusGeometry(0.15, 0.025, 12, 48),
  new THREE.MeshBasicMaterial({ color: 0x050505 })
);
originRing.rotation.x = Math.PI / 2;
originRing.position.y = 0.018;
scene.add(originRing);

function makeArrow({
  shaftColor = 0x008000,
  coneColor = shaftColor,
  radius = 0.025,
  coneRadius = 0.11,
  coneLength = 0.28,
  opacity = 1
} = {}) {
  const group = new THREE.Group();
  const shaftMat = new THREE.MeshBasicMaterial({
    color: shaftColor,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
  const coneMat = new THREE.MeshBasicMaterial({
    color: coneColor,
    transparent: opacity < 1,
    opacity,
    depthWrite: opacity >= 1
  });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 16), shaftMat);
  const cone = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 24), coneMat);
  group.add(shaft, cone);
  group.userData.radius = radius;
  group.userData.coneRadius = coneRadius;
  group.userData.coneLength = coneLength;
  group.userData.shaft = shaft;
  group.userData.cone = cone;
  scene.add(group);
  return group;
}

const yAxis = new THREE.Vector3(0, 1, 0);

function updateArrow(group, start, dir, length) {
  const direction = dir.clone();
  if (direction.lengthSq() < 1e-9) direction.set(0, 1, 0);
  direction.normalize();

  const coneLength = Math.min(group.userData.coneLength, Math.max(0.07, length * 0.38));
  const shaftLength = Math.max(0.001, length - coneLength);
  const quat = new THREE.Quaternion().setFromUnitVectors(yAxis, direction);

  const shaft = group.userData.shaft;
  shaft.position.copy(start).addScaledVector(direction, shaftLength / 2);
  shaft.quaternion.copy(quat);
  shaft.scale.set(group.userData.radius, shaftLength, group.userData.radius);

  const cone = group.userData.cone;
  cone.position.copy(start).addScaledVector(direction, shaftLength + coneLength / 2);
  cone.quaternion.copy(quat);
  cone.scale.set(group.userData.coneRadius, coneLength, group.userData.coneRadius);

  group.userData.start = start.clone();
  group.userData.dir = direction.clone();
  group.userData.length = length;
}

function setArrowOpacity(group, opacity) {
  group.children.forEach((child) => {
    child.material.opacity = opacity;
    child.material.transparent = opacity < 1;
    child.material.depthWrite = opacity >= 1;
    child.material.needsUpdate = true;
  });
}

const incomingRay = makeArrow({
  shaftColor: 0xffdf00,
  coneColor: 0xff3a22,
  radius: 0.055,
  coneRadius: 0.18,
  coneLength: 0.46
});
registerInteractive(incomingRay, {
  title: 'Incoming radiance ℓᵢₙ(λ)',
  tooltip: 'Incoming light ray',
  body: 'This yellow-orange ray represents incident radiance arriving at wavelength λ before it interacts with the surface.'
});

const pArrow = makeArrow({
  shaftColor: 0xff1616,
  coneColor: 0xff1616,
  radius: 0.035,
  coneRadius: 0.135,
  coneLength: 0.32
});
registerInteractive(pArrow, {
  title: 'Incoming direction p',
  tooltip: 'p: incoming direction',
  body: 'The vector p is the local incident direction used as an argument of the BRDF.'
});

const normalArrow = makeArrow({
  shaftColor: 0x000000,
  coneColor: 0x000000,
  radius: 0.036,
  coneRadius: 0.145,
  coneLength: 0.32
});
registerInteractive(normalArrow, {
  title: 'Surface normal n',
  tooltip: 'n: surface normal',
  body: 'The surface normal defines the local hemisphere into which the BRDF scatters outgoing radiance.'
});

const qArrow = makeArrow({
  shaftColor: 0x0c8200,
  coneColor: 0x0c8200,
  radius: 0.048,
  coneRadius: 0.19,
  coneLength: 0.40
});
registerInteractive(qArrow, {
  title: 'Outgoing direction q',
  tooltip: 'q: outgoing direction',
  body: 'The highlighted green vector q is one outgoing/viewing direction. In the glossy case, the lobe concentrates around the mirror-reflection direction.'
});

const scatterArrows = [];
const scatterSpecs = [];
[
  { polar: 0, count: 1, phase: 0 },
  { polar: 30, count: 8, phase: 0 },
  { polar: 58, count: 8, phase: Math.PI / 8 }
].forEach((ring) => {
  for (let i = 0; i < ring.count; i++) {
    scatterSpecs.push({
      polar: THREE.MathUtils.degToRad(ring.polar),
      phi: ring.count === 1 ? 0 : ring.phase + (i / ring.count) * Math.PI * 2
    });
  }
});

scatterSpecs.forEach(() => {
  const a = makeArrow({
    shaftColor: 0x34c900,
    coneColor: 0x36cf00,
    radius: 0.024,
    coneRadius: 0.125,
    coneLength: 0.27,
    opacity: 0.52
  });
  scatterArrows.push(a);
  registerInteractive(a, {
    title: 'Scattered outgoing radiance',
    tooltip: 'One BRDF outgoing direction',
    body: 'The green cluster samples many possible outgoing directions. Lambertian reflection spreads them evenly; glossy reflection weights directions near the specular reflection.'
  });
});

const angleGeom = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, 0, 0),
  new THREE.Vector3(0.25, 0, 0)
]);
const angleLine = new THREE.Line(
  angleGeom,
  new THREE.LineBasicMaterial({ color: 0x000000 })
);
scene.add(angleLine);

const labelEntries = {
  lin: null,
  p: null,
  n: null,
  q: null,
  lout: null
};

function localFrame() {
  const tilt = THREE.MathUtils.degToRad(state.normalTilt);
  const n = new THREE.Vector3(Math.sin(tilt), Math.cos(tilt), 0).normalize();
  const t = new THREE.Vector3(Math.cos(tilt), -Math.sin(tilt), 0).normalize();
  const b = new THREE.Vector3(0, 0, 1);
  return { n, t, b };
}

function currentDirections() {
  const { n, t, b } = localFrame();
  const theta = THREE.MathUtils.degToRad(state.incidentTheta);
  const incidentTowardSurface = new THREE.Vector3()
    .copy(t).multiplyScalar(Math.sin(theta))
    .addScaledVector(n, -Math.cos(theta))
    .normalize();
  const reflected = new THREE.Vector3()
    .copy(t).multiplyScalar(Math.sin(theta))
    .addScaledVector(n, Math.cos(theta))
    .normalize();
  return { n, t, b, incidentTowardSurface, reflected };
}

function moveLabel(entry, pos) {
  if (entry) entry.pos.copy(pos);
}

function updateLabelPositions(positions) {
  moveLabel(labelEntries.lin, positions.lin);
  moveLabel(labelEntries.p, positions.p);
  moveLabel(labelEntries.n, positions.n);
  moveLabel(labelEntries.q, positions.q);
  moveLabel(labelEntries.lout, positions.lout);
}

function updateScene() {
  state.brdfType = ui.brdfType.value;
  state.incidentTheta = Number(ui.incidentTheta.value);
  state.normalTilt = Number(ui.normalTilt.value);

  ui.incidentThetaVal.textContent = `${state.incidentTheta}°`;
  ui.normalTiltVal.textContent = `${state.normalTilt}°`;

  const { n, t, b, incidentTowardSurface, reflected } = currentDirections();
  const origin = new THREE.Vector3(0, 0.025, 0);

  const incomingStart = incidentTowardSurface.clone().multiplyScalar(-5.0).add(origin);
  updateArrow(incomingRay, incomingStart, incidentTowardSurface, incomingStart.distanceTo(origin) - 0.03);

  const pStart = incidentTowardSurface.clone().multiplyScalar(-1.45).add(origin);
  updateArrow(pArrow, pStart, incidentTowardSurface, 1.27);

  updateArrow(normalArrow, origin, n, 1.42);
  updateArrow(qArrow, origin, reflected, 2.25);

  scatterArrows.forEach((arrow, i) => {
    const spec = scatterSpecs[i];
    const hemiDir = new THREE.Vector3()
      .copy(n).multiplyScalar(Math.cos(spec.polar))
      .addScaledVector(t, Math.sin(spec.polar) * Math.cos(spec.phi))
      .addScaledVector(b, Math.sin(spec.polar) * Math.sin(spec.phi))
      .normalize();

    let length;
    let opacity;
    if (state.brdfType === 'Lambertian') {
      length = 0.78 + 0.22 * Math.cos(spec.polar);
      opacity = 0.48;
    } else {
      const align = Math.max(0, hemiDir.dot(reflected));
      const weight = Math.pow(align, 14);
      length = 0.24 + 1.75 * weight;
      opacity = 0.18 + 0.72 * weight;
    }

    updateArrow(arrow, origin, hemiDir, length);
    setArrowOpacity(arrow, opacity);
  });

  const s = 0.34;
  angleGeom.setFromPoints([
    origin.clone().addScaledVector(t, s),
    origin.clone().addScaledVector(t, s).addScaledVector(n, s),
    origin.clone().addScaledVector(n, s),
    origin.clone()
  ]);
  angleGeom.computeBoundingSphere();

  updateLabelPositions({
    lin: incomingStart.clone().lerp(origin, 0.34).add(new THREE.Vector3(-0.18, 0.43, 0.10)),
    p: pStart.clone().lerp(origin, 0.50).add(new THREE.Vector3(-0.18, 0.22, 0.02)),
    n: origin.clone().addScaledVector(n, 1.08).add(new THREE.Vector3(-0.16, 0.12, 0.02)),
    q: origin.clone().addScaledVector(reflected, 1.12).add(new THREE.Vector3(0.16, 0.17, 0.03)),
    lout: origin.clone().addScaledVector(reflected, 2.42).add(new THREE.Vector3(0.70, 0.48, 0.08))
  });
}

ui.brdfType.addEventListener('change', updateScene);
ui.incidentTheta.addEventListener('input', updateScene);
ui.normalTilt.addEventListener('input', updateScene);

