}

function updateLabelPositions(positions) {
  moveLabel(labelEntries.lin, positions.lin);
  moveLabel(labelEntries.p, positions.p);
  moveLabel(labelEntries.n, positions.n);
  moveLabel(labelEntries.q, positions.q);
  moveLabel(labelEntries.lout, positions.lout);
}

function updateScene() {
  state.brdfType = ui.brdfType.value;
  state.incidentTheta = Number(ui.incidentTheta.value);
  state.normalTilt = Number(ui.normalTilt.value);

  ui.incidentThetaVal.textContent = `${state.incidentTheta}°`;
  ui.normalTiltVal.textContent = `${state.normalTilt}°`;

  const { n, t, b, incidentTowardSurface, reflected } = currentDirections();
  const origin = new THREE.Vector3(0, 0.025, 0);

  const incomingStart = incidentTowardSurface.clone().multiplyScalar(-5.0).add(origin);
  updateArrow(incomingRay, incomingStart, incidentTowardSurface, incomingStart.distanceTo(origin) - 0.03);

  const pStart = incidentTowardSurface.clone().multiplyScalar(-1.45).add(origin);
  updateArrow(pArrow, pStart, incidentTowardSurface, 1.27);

  updateArrow(normalArrow, origin, n, 1.42);
  updateArrow(qArrow, origin, reflected, 2.25);

  scatterArrows.forEach((arrow, i) => {
    const spec = scatterSpecs[i];
    const hemiDir = new THREE.Vector3()
      .copy(n).multiplyScalar(Math.cos(spec.polar))
      .addScaledVector(t, Math.sin(spec.polar) * Math.cos(spec.phi))
      .addScaledVector(b, Math.sin(spec.polar) * Math.sin(spec.phi))
      .normalize();

    let length;
    let opacity;
    if (state.brdfType === 'Lambertian') {
      length = 0.78 + 0.22 * Math.cos(spec.polar);
      opacity = 0.48;
    } else {
      const align = Math.max(0, hemiDir.dot(reflected));
      const weight = Math.pow(align, 14);
      length = 0.24 + 1.75 * weight;
      opacity = 0.18 + 0.72 * weight;
    }

    updateArrow(arrow, origin, hemiDir, length);
    setArrowOpacity(arrow, opacity);
  });

  const s = 0.34;
  angleGeom.setFromPoints([
    origin.clone().addScaledVector(t, s),
    origin.clone().addScaledVector(t, s).addScaledVector(n, s),
    origin.clone().addScaledVector(n, s),
    origin.clone()
  ]);
  angleGeom.computeBoundingSphere();

  updateLabelPositions({
    lin: incomingStart.clone().lerp(origin, 0.34).add(new THREE.Vector3(-0.18, 0.43, 0.10)),
    p: pStart.clone().lerp(origin, 0.50).add(new THREE.Vector3(-0.18, 0.22, 0.02)),
    n: origin.clone().addScaledVector(n, 1.08).add(new THREE.Vector3(-0.16, 0.12, 0.02)),
    q: origin.clone().addScaledVector(reflected, 1.12).add(new THREE.Vector3(0.16, 0.17, 0.03)),
    lout: origin.clone().addScaledVector(reflected, 2.42).add(new THREE.Vector3(0.70, 0.48, 0.08))
  });
}

