window.goToStep = function goToStep(index) {
  currentStep = (index + steps.length) % steps.length;
  const target = steps[currentStep].state;
  const start = {
    brdfType: ui.brdfType.value,
    incidentTheta: Number(ui.incidentTheta.value),
    normalTilt: Number(ui.normalTilt.value)
  };

  applyStepText();
  if (tweenTimer) clearInterval(tweenTimer);
  ui.brdfType.value = target.brdfType;

  const t0 = performance.now();
  const duration = 540;
  tweenTimer = setInterval(() => {
    const a = Math.min(1, (performance.now() - t0) / duration);
    const ease = a * a * (3 - 2 * a);
    ui.incidentTheta.value = Math.round((start.incidentTheta + (target.incidentTheta - start.incidentTheta) * ease) / 5) * 5;
    ui.normalTilt.value = Math.round((start.normalTilt + (target.normalTilt - start.normalTilt) * ease) / 5) * 5;
    updateScene();

    if (a >= 1) {
      clearInterval(tweenTimer);
      tweenTimer = null;
      setControlsFromState(target);
    }
  }, 16);
};

ui.prevStep.addEventListener('click', () => window.goToStep(currentStep - 1));
