<!-- @FIGURE_UI_BEGIN -->
<label>BRDF Model
  <select id="brdfType" style="font-size:11px">
    <option>Lambertian</option>
    <option>Glossy (Phong)</option>
  </select>
</label>
<label>Incident Angle (θ<sub>i</sub>) <span id="incidentThetaVal">45°</span>
