</label>
<div style="display:flex;gap:3px;align-items:center">
  <button id="prevStep" type="button">◀</button>
  <button id="nextStep" type="button">Step ▶</button>
</div>
<div id="stepTitle" style="font-weight:bold;text-shadow:0 1px 2px #fff">Lambertian Reflection</div>
